for tid, title, icon, color, summary, topics in tracks:
    ts = []
    for t in topics:
        slug = tid + "-" + re.sub(r'[^a-z0-9]+', '-', t["title"].lower()).strip('-')[:40]
        assert slug not in seen, slug; seen.add(slug)
        docs = []
        for k in t["docs"]:
            n, u = D[k]; docs.append({"title": n, "url": u})
        ts.append({"id": slug, "title": t["title"], "level": t["level"], "summary": t["summary"], "videos": t["videos"], "docs": docs})
    out_tracks.append({"id": tid, "title": title, "icon": icon, "color": color, "summary": summary, "topics": ts})

